      s.x = x;
      s.y = y;
      s.radiusX = radius;
      s.radiusY = 0;
      s.damage = damage;
      s.hitTally = 0;
      s.angle = 0;
      s.cadenceCounter = cadenceCounter;
      s.cadenceDivisor = Math.max(1, cadenceDivisor | 0);
