      s.x = x;
      s.y = y;
      s.radiusX = width;
      s.radiusY = height;
      s.damage = damage;
      s.hitTally = 0;
      s.angle = angle;
      s.cadenceCounter = cadenceCounter;
      s.cadenceDivisor = Math.max(1, cadenceDivisor | 0);
      s.active = true;
      s.source = source;
      s.shape = "box";
