      if (e.ecl.th08 && (e.ecl.th08.flags & 16) !== 0) return;
      if (e.ecl.th08?.familiar && e.ecl.th08.sideBit === 1) return;
      if (!e.ecl.shotCollision || !e.ecl.interactable || e.dead) return;
      this.collidePlayerShotsInBox(e, e.ecl.hitbox);
